def digest(self, *args):
    assert len(args) > 1, u'Too few arguments'
    challenge = hmac.new(self.__key, str(args[0]), hashlib.sha1)
    for arg in args[1:]:
        challenge.update(str(args))
    return challenge.hexdigest()

def digest(self, *args):
    assert len(args) > 1, u'Too few arguments'
    challenge = hmac.new(self.__key, str(args[0]), hashlib.sha1)
    for arg in args[1:]:
        challenge.update(str(arg))
    return challenge.hexdigest()

