def hit_highlight(self, hits = [], **kwargs):
    if not hits and not kwargs.get('query'):
        return self.text

    if not hits and kwargs.get('query'):
        stripped_text   =   strip_tags(self.text)
        for match in re.finditer(u'%s' % kwargs.get('query'), stripped_text):
            hits.append(match.span())

    if hits and not type(hits) == list:
        raise Exception('The syntax for the hit_highlight method has changed. You must pass in a list of lists containing the indices of the strings you want to match.')

    tag_name = kwargs.get('tag', DEFAULT_HIGHLIGHT_TAG)
    tags = [u'<%s>' % tag_name, u'</%s>' % tag_name]

    text = self.text
    chunks = re.split(r'[<>]', text)
    text_chunks = []
    for index, chunk in enumerate(chunks):
        if not index % 2:
            text_chunks.append(chunk)
    for hit in sorted(hits, key = lambda chunk: chunk[1], reverse = True):
        hit_start, hit_end = hit
        placed = 0
        for index, chunk in enumerate(chunks):
            if placed == 2:
                continue
            if index % 2:
                # we're inside a <tag>
                continue
            chunk_start = len(u''.join(text_chunks[0:index / 2]))
            chunk_end = chunk_start + len(chunk)
            if hit_start >= chunk_start and hit_start < chunk_end:
                chunk = chunk[:hit_start - chunk_start] + tags[0] + chunk[hit_start - chunk_start:]
                if hit_end <= chunk_end:
                    hit_end += len(tags[0])
                    chunk_end += len(tags[0])
                placed = 1
            if hit_end > chunk_start and hit_end <= chunk_end:
                chunk = chunk[:hit_end - chunk_start] + tags[1] + chunk[hit_end - chunk_start:]
                placed = 2
            chunks[index] = chunk
        if placed == 1:
            chunks[-1] = chunks[-1] + tags[1]
    result = []
    for index, chunk in enumerate(chunks):
        if index % 2:
            # we're inside a <tag>
            result.append(u'<%s>' % chunk)
        else:
            result.append(chunk)
    self.text = u''.join(result)
    return self.text

def hit_highlight(self, hits = [], **kwargs):
    if not hits and not kwargs.get('query'):
        return self.text

    if not hits and kwargs.get('query'):
        stripped_text   =   strip_tags(self.text)
        for match in re.finditer(u'%s' % kwargs.get('query'), stripped_text):
            hits.append(match.span())

    if hits and not type(hits) == list:
        raise Exception('The syntax for the hit_highlight method has changed. You must pass in a list of lists containing the indices of the strings you want to match.')

    tag_name = kwargs.get('tag', DEFAULT_HIGHLIGHT_TAG)
    tags = [u'<%s>' % tag_name, u'</%s>' % tag_name]

    text = self.text
    chunks = re.split(r'[<>]', text)
    text_chunks = []
    for index, chunk in enumerate(chunks):
        if not index % 2:
            text_chunks.append(chunk)
    for hit in sorted(hits, key = lambda chunk: chunk[1], reverse = True):
        hit_start, hit_end = hit
        placed = 0
        for index, chunk in enumerate(chunks):
            if placed == 2:
                continue
            if index % 2:
                # we're inside a <tag>
                continue
            chunk_start = len(u''.join(text_chunks[0:index // 2]))
            chunk_end = chunk_start + len(chunk)
            if hit_start >= chunk_start and hit_start < chunk_end:
                chunk = chunk[:hit_start - chunk_start] + tags[0] + chunk[hit_start - chunk_start:]
                if hit_end <= chunk_end:
                    hit_end += len(tags[0])
                    chunk_end += len(tags[0])
                placed = 1
            if hit_end > chunk_start and hit_end <= chunk_end:
                chunk = chunk[:hit_end - chunk_start] + tags[1] + chunk[hit_end - chunk_start:]
                placed = 2
            chunks[index] = chunk
        if placed == 1:
            chunks[-1] = chunks[-1] + tags[1]
    result = []
    for index, chunk in enumerate(chunks):
        if index % 2:
            # we're inside a <tag>
            result.append(u'<%s>' % chunk)
        else:
            result.append(chunk)
    self.text = u''.join(result)
    return self.text

def import_function(filename):
    if os.path.isabs(filename):
        filepath = filename
    else:
        filepath = os.path.join(current_dir, filename)

    import_dirs = [base_dir]
    import_path = os.environ.get('YGLU_IMPORT_ALLOW')
    if import_path is not None:
        import_dirs.extend(import_path.split(os.pathsep))

    allow = False
    for dir in import_dirs:
        relative_path = os.path.relpath(filepath, start=dir)
        if not relative_path.startswith(os.pardir):
            allow = True
            break
    if not allow:
        raise Exception(
            'Import not allowed. Set $YGLU_IMPORT_ALLOW to allow import from other directories')

    with open(filepath) as file:
        if hasattr(root, 'doc'):
            errors = root.doc.errors
        else:
            errors = None
        result = build(file, filename, errors)
        return Holder(result)

