@classmethod
def get_parse_trade_url(cls, trade_url):
    regex = re.compile(r'^https?://steamcommunity\.com/tradeoffer/new/\?partner=(\d+)&token=([a-zA-Z0-9_-]+)$')
    match = regex.match(trade_url)
    if match:
        return None

    return {
        'token': match.group(1),
        'partner': match.group(2),
    }

