        white_list = json.loads(response.body.decode('utf8'))['hooks']

        for valid_ip in white_list:
            if remote_ip in ip_network(valid_ip):
                break
        else:
            raise HTTPError(code=403)

    if options.GITHUB_SECRET:
        # only SHA1 is supported
        sha_name, signature = self.request.headers.get('X-Hub-Signature').split('=')
        if sha_name != 'sha1':
            raise HTTPError(code=501)

        # HMAC requires the key to be bytes, but data is string
        mac = hmac.new(options.GITHUB_SECRET.encode(), msg=self.request.body, digestmod=sha1)

        if not hmac.compare_digest(str(mac.hexdigest()), str(signature)):
            raise HTTPError(code=403)

    logging.warning('GutHub pull ...')

    event = self.request.headers.get('X-GitHub-Event', 'ping')
    self.set_header('Content-Type', 'application/json')

    # ping
    if event == 'ping':
        return json.dumps({'msg': 'pong'})

    if event == 'push':
        ref = json.loads(self.request.body.decode('utf8'))['ref']
        if ref == 'refs/heads/{branch}'.format(branch=options.GITHUB_BRANCH):
            result = yield github_pull()
            logger.warning(result)

def update(self):
    """Update WazeRouteCalculator Sensor."""
    if self.origin is not None and self.destination is not None:
        try:
            params = self._calc.WazeRouteCalculator(
                self.origin, self.destination, self.region,
                self.vehicle_type, log_lvl=logging.DEBUG)
            routes = params.calc_all_routes_info(real_time=self.realtime)

            if self.include is not None:
                routes = {k: v for k, v in routes.items() if
                          self.include.lower() in k.lower()}

            if self.exclude is not None:
                routes = {k: v for k, v in routes.items() if
                          self.exclude.lower() in k.lower()}

            route = sorted(routes, key=(lambda key: routes[key][0]))[0]

            self.duration, distance = routes[route]

            if self.units == CONF_UNIT_SYSTEM_IMPERIAL:
                # Convert to miles.
                self.distance = distance / 1.609
            else:
                self.distance = distance

            self.route = route
        except self._calc.WRCError as exp:
            _LOGGER.warning("Error on retrieving data: %s", exp)
            return
        except KeyError:
            _LOGGER.error("Error retrieving data from server")
            return

