@staticmethod
def _check_and_parse_output_plugin(string):
    try:
        raw_ouputs = string.split(';')
        outputs = []
        for output in raw_ouputs:
            name, arguments = output.split(':')
            outputs.append((name, arguments))
        if len(output) == 0:
            raise ValueError()
    except ValueError:
        raise RuntimeError('Incorrect output plugin string')
    return outputs

