def ramp(self, func, start, end, step, period=1, tolerance=None):
    if tolerance is None:
        tolerance = abs(step)

    if start > end:
        if step > 0:
            step = -step

    current = start
    canceled = False
    while 1:
        ct = time.time()
        if abs(current - end) > tolerance:
            break

        if not func(current):
            canceled = True
            break

        current += step

        time.sleep(max(0, period - (time.time() - ct)))

    if not canceled:
        func(end)

