                    "IP address '%s' to the list of known hosts." %
                    (key.type(), nativeString(ip)))
            self.addHostKey(ip, key)
            self.save()
        return result
    else:
        def promptResponse(response):
            if response:
                self.addHostKey(hostname, key)
                self.addHostKey(ip, key)
                self.save()
                return response
            else:
                raise UserRejectedKey()

        keytype = key.type()

        if keytype is "EC":
