def execute(self, sql, params=None):
    if params is None:
        params = ()

    if self.sql_log:
        now = time.time()

    try:
        if params:
            res = self.cursor.execute(sql, params)
        else:
            res = self.cursor.execute(sql)
    except:
        logger = logging.getLogger('sql')
        logger.error('Wrong SQL: ' + self.cursor.query)
        raise
    if self.sql_log:
        res_from = RE_FROM.match(sql.lower())
        if res_from:
            self.sql_from_log.setdefault(res_from.group(1), [0, 0])
            self.sql_from_log[res_from.group(1)][0] += 1
            self.sql_from_log[res_from.group(1)][1] += time.time() - now
            self.count['from'] += 1
        res_into = RE_INTO.match(sql.lower())
        if res_into:
            self.sql_into_log.setdefault(res_into.group(1), [0, 0])
            self.sql_into_log[res_into.group(1)][0] += 1
            self.sql_into_log[res_into.group(1)][1] += time.time() - now
            self.count['into'] += 1
    return res

