def doparse(url,d):
    parm = {}
    path = url.split("://")[1]
    delim = path.find("@");
    if delim != -1:
        (user,pswd,host,port) = path.split('@')[0].split(":")
        path = path.split('@')[1]
    else:
        (host,port) = data.getVar('P4PORT', d).split(':')
        user = ""
        pswd = ""

    if path.find(";") != -1:
        keys=[]
        values=[]
        plist = path.split(';')
        for item in plist:
            if item.count('='):
                (key,value) = item.split('=')
                keys.append(key)
                values.append(value)

        parm = dict(zip(keys,values))
    path = "//" + path.split(';')[0]
    host += ":%s" % (port)
    parm["cset"] = Perforce.getcset(d, path, host, user, pswd, parm)

    return host,path,user,pswd,parm

