def filename_items_for_filetype(filenames, filetype_info):
    """Iterate over the filenames matching *filetype_info*."""
    if not isinstance(filenames, set):
        # we perform set operations later on to improve performance
        filenames = set(filenames)
    matched_files = []
    for pattern in filetype_info['file_patterns']:
        matches = match_filenames(filenames, pattern)
        filenames -= matches
        for filename in matches:
            try:
                filename_info = parse(
                    pattern, get_filebase(filename, pattern))
            except ValueError:
                logger.debug("Can't parse %s with %s.", filename, pattern)
                continue
            matched_files.append(filename)
            yield filename, filename_info

@staticmethod
def filename_items_for_filetype(filenames, filetype_info):
    """Iterate over the filenames matching *filetype_info*."""
    if not isinstance(filenames, set):
        # we perform set operations later on to improve performance
        filenames = set(filenames)
    matched_files = []
    for pattern in filetype_info['file_patterns']:
        matches = match_filenames(filenames, pattern)
        filenames -= set(matches)
        for filename in matches:
            try:
                filename_info = parse(
                    pattern, get_filebase(filename, pattern))
            except ValueError:
                logger.debug("Can't parse %s with %s.", filename, pattern)
                continue
            matched_files.append(filename)
            yield filename, filename_info

def errorEstimation_GA(df, d2f, R, C, delta):
    """CCLS error estimation, valid also for non-linear fitting. R could
    be R = inv(cov), or the diagonal of that, or some other symmetric
    matrix of our choosing. With N sampling points, and k parameters
    we have:

    df     is a  k x N      dimensional array
    d2f    is a  k x k x N  dimensional array
    delta  is a  N          dimensional array

    """
    q = len(df)
    N = len(R)

    first_term = np.zeros((q,q), dtype=np.float64)
    for a in range(q):
        for b in range(q):
            for i in range(N):
                for j in range(N):
                    first_term[a,b] = first_term[a,b] + 2 * d2f[a,b,j] * R[i,j] * delta[j]

    second_term = 2 * np.dot(np.dot(df,R),np.transpose(df))

    hessian = first_term + second_term

    H_inv = np.linalg.inv(hessian)
    RCR = np.dot(R,np.dot(C,R))

    error = np.zeros((q,q), dtype=np.float64)
    for a in range(q):
        for b in range(q):
            for c in range(q):
                for d in range(q):
                    dfRCRdf = np.dot(df[c],np.dot(RCR,np.transpose(df[d])))
                    error[a,b] = error[a,b] + 4 * H_inv[a,c] * dfRCRdf * H_inv[d,b]

    return(error.diagonal())

