def write(self, data):
    bytes_written = ctypes.c_uint()
    e = lib.fscc_write_with_blocking(self._handle, data, len(data),
                                     ctypes.byref(bytes_written))

    if e == 0:
        pass
    elif e == FSCC_BUFFER_TOO_SMALL:
        raise BufferTooSmallError()
    elif e == FSCC_TIMEOUT:
        raise TimeoutError()
    else:
        raise Exception(e)

    return bytes_written

