def get_combination_pairs(self, sents):
    all_sents = []
    k = self.k
    n = min(len(sents[:30])+1, k[1]+1)

    if min(n, k[0]) > len(sents[:30]):
        return range(0, len(sents[:30]))

    sentences = np.array(sents)
    for i in range(k[0],n):
        pairs = self.get_combinations(len(sentences[:30]), i)
        all_sents.extend([p for p in pairs])

    return all_sents

def right_limit_list(self):
    """Returns a list with every right limit (inorder)"""
    result = []
    if self.content:
        result.append(self.content.rightpos)
    for x in self.childlist:
        result += x.right_limit_list()
    if not result:
        result = [0]
    return result

