@classmethod
def load_data(cls, dataname):
    if isinstance(dataname, np.ndarray):
        return dataname
    if not hasattr(cls, '_datasets'):
        cls._datasets = {}
        for ds in DATASETS:
            cls._datasets.update(np.load(ds))
    return cls._datasets[dataname].astype(dtype)

